@push('scripts')<script>document.getElementById('add-item').addEventListener('click',function(){const container=document.getElementById('readiness-items');const index=container.children.length;if(index>=100)return;const row=document.getElementById('item-template').content.cloneNode(true);row.querySelectorAll('[data-field]').forEach(function(input){input.name='items['+index+']['+input.dataset.field+']';input.id='item-'+index+'-'+input.dataset.field;input.previousElementSibling.htmlFor=input.id;});container.appendChild(row);});</script>@endpush
